def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n <= 4:
        return 'C'

    my_last, opp_last = history[-1]

    total_opp_d = 0
    total_my_d = 0
    my_d_opp_c = 0
    for m, o in history:
        if o == 'D':
            total_opp_d += 1
        if m == 'D':
            total_my_d += 1
            if o == 'C':
                my_d_opp_c += 1

    recent = history[-10:] if n >= 10 else history
    opp_d10 = 0
    my_d10 = 0
    for m, o in recent:
        if o == 'D':
            opp_d10 += 1
        if m == 'D':
            my_d10 += 1

    streak_opp_d = 0
    my_c_in_streak = 0
    my_d_in_streak = 0
    for m, o in reversed(history):
        if o == 'D':
            streak_opp_d += 1
            if m == 'C':
                my_c_in_streak += 1
            else:
                my_d_in_streak += 1
        else:
            break

    punish_count = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i][1] == 'C' and history[i + 1][1] == 'D':
            punish_count += 1

    opp_rate = total_opp_d / n

    if n >= 60 and punish_count == 0 and opp_d10 == 0 and opp_rate <= 0.20:
        if my_d_opp_c >= 1:
            if (n >= 90 and my_d_opp_c >= 5) or n >= 95:
                return 'D'
            if my_last == 'D':
                return 'C'
            return 'D'
        elif n >= 80 and total_my_d == 0:
            return 'D'

    if opp_last == 'C':
        if my_last == 'D':
            return 'C'
        if total_opp_d > 0 and (opp_rate >= 0.55 or opp_d10 >= 5 or (opp_rate >= 0.40 and opp_d10 >= 4)):
            return 'D'
        return 'C'

    if streak_opp_d >= 2 and (total_opp_d - streak_opp_d) <= 3 and opp_rate <= 0.35:
        if my_d_in_streak >= 2:
            if my_c_in_streak >= 5:
                return 'D'
            return 'C'
        return 'D'

    if streak_opp_d == 1 and my_last == 'C':
        if history[-2][1] == 'C' or opp_d10 <= 2 or opp_rate <= 0.25:
            return 'C'

    if streak_opp_d >= 2 or opp_d10 >= 5 or opp_rate >= 0.55:
        return 'D'

    if opp_rate <= 0.25 and opp_d10 <= 2:
        return 'C'

    if my_d10 >= 3 and opp_rate <= 0.35 and opp_d10 <= 3:
        return 'C'

    if opp_rate <= 0.35:
        if opp_d10 <= 1:
            return 'C'
        return 'D' if rng.random() < 0.60 else 'C'

    if opp_rate < 0.60:
        return 'D'

    return 'D' if rng.random() < 0.90 else 'C'
